package com.amplayer.portable;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.graphics.*;import org.json.*;
public class NativePlayback211Instrumentation extends Instrumentation {
 private Bundle arguments;
 private void report(String key,String value){Bundle b=new Bundle();b.putString(key,value);sendStatus(0,b);}
 @Override public void onCreate(Bundle args){arguments=args;super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  JSONObject settings=Store.load(getTargetContext());settings.put("autoUpdate",false);settings.put("language","zh-Hant");settings.put("theme","cyan");settings.put("volume",0);Store.save(getTargetContext(),settings.toString());
  Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2000);
  runOnMainSync(()->{View root=activity.getWindow().getDecorView();android.graphics.Insets bars=root.getRootWindowInsets().getInsets(WindowInsets.Type.systemBars());View content=((android.view.ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);View web=((android.view.ViewGroup)content).getChildAt(0);int[] pos=new int[2];web.getLocationOnScreen(pos);if(bars.top<=0||pos[1]<bars.top)throw new AssertionError("Status overlap: "+pos[1]+"/"+bars.top);report("insets","PASS actual WebView top="+pos[1]+", system bar="+bars.top);});
  String[] ids={"78fm9wyy2tzuv","ndk05tyy2tzuv","aw9uqyxy2tzuv","p2e3rfg3qtzuv"};String[] names={"中廣新聞網","中廣音樂網","中廣流行網","中廣鄉親網"};
  for(int i=0;i<(arguments.getString("notificationOnly","false").equals("true")?1:ids.length);i++){
   JSONObject item=new JSONObject().put("type","radio").put("name",names[i]).put("url","https://stream.rcs.revma.com/"+ids[i]).put("region","TW");
   runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",item.toString())));JSONObject status=new JSONObject();boolean playing=false;long start=SystemClock.elapsedRealtime();
   for(int n=0;n<100;n++){Thread.sleep(600);status=new JSONObject(PlaybackService.status());if(status.optJSONObject("item")!=null&&status.optJSONObject("item").optString("url").equals(item.optString("url"))&&status.optBoolean("playing")&&status.optLong("position")>1500){playing=true;break;}}
   report("station"+i,names[i]+" "+(playing?"PASS":"FAIL")+" waitMs="+(SystemClock.elapsedRealtime()-start)+" "+status);if(!playing)throw new Exception("Stream did not decode: "+names[i]);
  }
  runOnMainSync(()->activity.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));for(int wait=0;wait<30;wait++){Thread.sleep(500);if(new JSONObject(PlaybackService.status()).optLong("backgroundDeadline")>0)break;}JSONObject background=new JSONObject(PlaybackService.status());long remaining=background.optLong("backgroundDeadline")-System.currentTimeMillis();if(remaining<3580000||remaining>3600000)throw new Exception("Automatic hour incorrect "+remaining);report("background","PASS playing="+background.optBoolean("playing")+", hour remaining="+remaining);
  boolean found=false;for(android.service.notification.StatusBarNotification entry:getTargetContext().getSystemService(NotificationManager.class).getActiveNotifications())if(entry.getId()==1){Notification n=entry.getNotification();if(n.color!=Color.parseColor("#191D23")||n.bigContentView==null)throw new Exception("Notification color/custom view missing");View view=n.bigContentView.apply(getTargetContext(),null);android.widget.TextView title=view.findViewById(R.id.notification_title),timer=view.findViewById(R.id.notification_timer);float sp=title.getTextSize()/getTargetContext().getResources().getDisplayMetrics().scaledDensity;if(sp<17||title.getCurrentTextColor()!=Color.parseColor("#F7F9FB")||timer.getVisibility()!=View.VISIBLE)throw new Exception("Notification font/countdown incorrect");android.widget.Chronometer clock=(android.widget.Chronometer)timer;if(!clock.isCountDown()||clock.getBase()<=SystemClock.elapsedRealtime())throw new Exception("Native countdown missing");android.widget.ViewFlipper dots=view.findViewById(R.id.notification_dots);if(dots.getChildCount()!=18||dots.getFlipInterval()!=1800)throw new Exception("Slow dots missing");long posted=entry.getPostTime();Thread.sleep(5500);for(android.service.notification.StatusBarNotification next:getTargetContext().getSystemService(NotificationManager.class).getActiveNotifications())if(next.getId()==1&&next.getPostTime()!=posted)throw new Exception("Notification reposted while timer running");report("notification","PASS 22sp title, native 24sp countdown, 18 slow dot frames, no periodic repost during 5.5s");found=true;}if(!found)throw new Exception("No notification");
  android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;getUiAutomation().setServiceInfo(info);getUiAutomation().executeShellCommand("cmd statusbar expand-notifications").close();Thread.sleep(1500);android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null){java.util.List<android.view.accessibility.AccessibilityNodeInfo> titles=root.findAccessibilityNodeInfosByText(names[0]);if(!titles.isEmpty()){android.view.accessibility.AccessibilityNodeInfo node=titles.get(0);for(int level=0;level<7&&node!=null;level++,node=node.getParent()){java.util.List<android.view.accessibility.AccessibilityNodeInfo> buttons=node.findAccessibilityNodeInfosByViewId("android:id/expand_button");if(!buttons.isEmpty()){buttons.get(0).performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);break;}}}}Thread.sleep(8500);Bitmap shot=getUiAutomation().takeScreenshot();if(shot!=null)try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"notification211.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}getUiAutomation().executeShellCommand("cmd statusbar collapse").close();
  runOnMainSync(()->activity.startActivity(new Intent(activity,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));Thread.sleep(1200);if(new JSONObject(PlaybackService.status()).optLong("backgroundDeadline")!=0)throw new Exception("Foreground did not clear timer");report("foreground","PASS timer cleared");
  result.putString("result","PASS");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}
